def decide(recipient_reputation, round_num, my_history):
    window_size = min(15, len(my_history))
    if window_size > 0:
        recent_actions = [h['action'] for h in my_history[-window_size:]]
        weights = [1 + i * 0.3 for i in range(window_size)]
        total = sum(weights)
        weighted_coops = sum(w for a, w in zip(recent_actions, weights) if a == 'cooperate')
        weighted_coop_rate = weighted_coops / total
    else:
        weighted_coop_rate = 0.5

