        base_prob = 0.75 + (recipient_reputation + 1) * 0.12
    elif round_num >= 25:
        base_prob = 0.25 + (recipient_reputation + 1) * 0.35
    else:
        base_prob = 0.4 * (recipient_reputation + 1) / 2 + 0.6 * weighted_coop_rate

    if weighted_coop_rate > 0.7:
        base_prob = min(1.0, base_prob + 0.08)
    elif weighted_coop_rate < 0.3:
        base_prob = max(0.0, base_prob - 0.08)

    base_prob = max(0.0, min(1.0, base_prob))
    return random.random() < base_prob

