import random

def evaluate(current_reputation, observation, my_history, round_num):
    action = observation['action']
    # Use exponential decay weighting - more recent actions have more impact
    decay = 0.8 ** (len(my_history)) if my_history else 1.0
    if action == 'cooperate':
        new_reputation = min(1.0, current_reputation + 0.2 * decay)
    else:
        new_reputation = max(-1.0, current_reputation - 0.2 * decay)
    return new_reputation

def decide(recipient_reputation, round_num, my_history):
    # Track cooperation patterns more carefully using sliding window
    window_size = min(10, len(my_history))
    if window_size > 0:
        recent_actions = [h['action'] for h in my_history[-window_size:]]
        coop_count = recent_actions.count('cooperate')
        defect_count = recent_actions.count('defect')
        coop_rate = coop_count / window_size

        # Detect patterns: look for streaks or cycles
        if len(recent_actions) >= 2:
            last_two = recent_actions[-2:]
            if last_two == ['cooperate', 'cooperate']:
                pattern_bonus = 0.15
            elif last_two == ['defect', 'defect']:
                pattern_bonus = -0.15
            else:
                pattern_bonus = 0.0
        else:
            pattern_bonus = 0.0

        # Special handling for mid-game where original was indecisive (rounds 10-20)
        if 10 <= round_num <= 20:
            # Be more aggressive with reputation signals in mid-game
            if recipient_reputation > 0.3:
                base_prob = 0.8 + pattern_bonus
            elif recipient_reputation < -0.3:
                base_prob = 0.2 + pattern_bonus
            else:
                # When reputation is near 0, rely more on pattern detection
                base_prob = 0.5 + pattern_bonus + (coop_rate * 0.2)
        elif round_num <= 5:
            # Early game: be more trusting
            base_prob = 0.7 + (recipient_reputation + 1) * 0.1 + pattern_bonus
        else:
            # Late game: be more selective
            base_prob = 0.3 + (recipient_reputation + 1) * 0.4 + pattern_bonus

        base_prob = max(0.0, min(1.0, base_prob))
    else:
        base_prob = 0.6

    return random.random() < base_prob
